#!/usr/bin/env bash
# ============================================================================
# EWA batch2-ewa — CORE-CONNECTED SATELLITES
# LockVault + RewardDistributor, both bound to EWA_Core (verified post-deploy).
#
# RUN (Termux):
#   cd ~/eva-contracts && git pull
#   export PK=0x...                 # founder signer key (never paste in chat)
#   export CONFIRM_DEFAULTS=yes     # ONLY after reviewing the defaults below
#   bash deployments/batch2-ewa-ewa.sh
#   unset PK && history -c
#
# Deployed addresses append to deployments/ewa-addresses.env (shared across
# batches). Every contract verifies on-chain post-deploy; any mismatch aborts.
# Founder signs every transaction. Nothing here touches mainnet by itself.
# ============================================================================
set -euo pipefail

RPC="${RPC:-https://mainnet.base.org}"
EWA_CORE=0x0201981D7BFE0E79DEACb0B5eae0F83022Cc18eB
FOUNDER=0xE9B0CebeF9e93cAc7727A06D5ED5f8e3AE71e5F8
ETHUSD_FEED=0x71041dddad3595F9CEd3DcCFBe3D1F4b0a16Bb70
: "${PK:?export PK=0x... first}"

echo "=================================================================="
echo "EWA batch2-ewa — CORE-CONNECTED SATELLITES"
echo "Founder: REVIEW these defaults/params before proceeding:"
echo "  lockvault token = EWA_CORE 0x0201981D7BFE0E79DEACb0B5eae0F83022Cc18eB"
echo "  rewardist token = EWA_CORE"
echo "  rewardist epoch = 86400 (1 day) [COORDINATOR DEFAULT - tell me to change it]"
echo "  NOTE: fund RewardDistributor ONLY via fund() - direct transfers are unaccounted (confirmed)"
echo "  boost: epoch=86400(1d) k=3 multBps=15000(1.5x) minBid=1 EWA [from tests]"
echo "  congexit: base=200bp k=4e18 cap=2500bp window=7d minLock=30d maxLock=365d [from tests]"
echo "  badge: minter=FOUNDER tiers=[1k,10k,100k,1M] EWA token-days [from tests] baseURI="" (founder branding)"
echo "  splitter: 100% FOUNDER [explicit default - changeable]"
echo "  vesting: 2M/1yr-cliff/3yr + 500k/1yr (previous EVA schedule as DOCUMENTED EXAMPLE - CONFIRM OR CHANGE)"
echo "=================================================================="
if [ "${CONFIRM_DEFAULTS:-}" != "yes" ]; then
  echo "ABORT: set CONFIRM_DEFAULTS=yes only after reviewing the above."
  exit 1
fi

ADDR_FILE="$(cd "$(dirname "$0")" && pwd)/ewa-addresses.env"
touch "$ADDR_FILE"
# shellcheck disable=SC1090
source "$ADDR_FILE"
save_addr() { printf '%s=%s\n' "$1" "$2" >> "$ADDR_FILE"; echo "  saved: $1=$2"; }
eq_addr() { [ "$(printf '%s' "$1" | tr 'A-Z' 'a-z')" = "$(printf '%s' "$2" | tr 'A-Z' 'a-z')" ]; }

DEPLOYER="$(cast wallet address --private-key "$PK")"
echo "deployer: $DEPLOYER"
echo "rpc: $RPC"
echo ""

# ===== EVA_LockVault =====
echo "=== EVA_LockVault ==="
LOCKVAULT_
LOCKVAULT_ARGS=$(cast abi-encode "constructor(address)" 0x0201981D7BFE0E79DEACb0B5eae0F83022Cc18eB)
LOCKVAULT_ARGS=${LOCKVAULT_ARGS#0x}
LOCKVAULT=$(cast send --rpc-url $RPC --private-key $PK --create ${LOCKVAULT_BC}${LOCKVAULT_ARGS} | grep -i contractAddress | awk '{print $2}')
if [ -z "${LOCKVAULT:-}" ]; then echo "FATAL: EVA_LockVault deploy failed"; exit 1; fi
echo "EVA_LockVault = $LOCKVAULT"
save_addr LOCKVAULT $LOCKVAULT
sleep 5
# verify: stored token == EWA_CORE
eq_addr "$(cast call $LOCKVAULT "EVA()(address)" --rpc-url $RPC)" "$EWA_CORE" || { echo "FATAL: EVA_LockVault token mismatch"; exit 1; }
sleep 5

# ===== EVA_RewardDistributor =====
# NOTE: epochLength 86400 = coordinator default (founder: adjust if needed)
echo "=== EVA_RewardDistributor ==="
REWARDIST_
REWARDIST_ARGS=$(cast abi-encode "constructor(address,uint256)" 0x0201981D7BFE0E79DEACb0B5eae0F83022Cc18eB 86400)
REWARDIST_ARGS=${REWARDIST_ARGS#0x}
REWARDIST=$(cast send --rpc-url $RPC --private-key $PK --create ${REWARDIST_BC}${REWARDIST_ARGS} | grep -i contractAddress | awk '{print $2}')
if [ -z "${REWARDIST:-}" ]; then echo "FATAL: EVA_RewardDistributor deploy failed"; exit 1; fi
echo "EVA_RewardDistributor = $REWARDIST"
save_addr REWARDIST $REWARDIST
sleep 5
eq_addr "$(cast call $REWARDIST "REWARD()(address)" --rpc-url $RPC)" "$EWA_CORE" || { echo "FATAL: EVA_RewardDistributor token mismatch"; exit 1; }
sleep 5


echo ""
echo "=================================================================="
echo "batch2-ewa complete — addresses this batch:"
echo "  LOCKVAULT=${LOCKVAULT:-MISSING}"
echo "  REWARDIST=${REWARDIST:-MISSING}"
# ===== EVA_BoostAuction =====
echo "=== EVA_BoostAuction ==="
BOOST_
BOOST_ARGS=$(cast abi-encode "constructor(address,uint256,uint256,uint256,uint256)" $EWA_CORE 86400 3 15000 1000000000000000000)
BOOST_ARGS=${BOOST_ARGS#0x}
BOOST=$(cast send --rpc-url $RPC --private-key $PK --create ${BOOST_BC}${BOOST_ARGS} | grep -i contractAddress | awk '{print $2}')
if [ -z "${BOOST:-}" ]; then echo "FATAL: EVA_BoostAuction deploy failed"; exit 1; fi
echo "EVA_BoostAuction = $BOOST"
save_addr BOOST $BOOST
sleep 5
eq_addr "$(cast call $BOOST "EVA()(address)" --rpc-url $RPC)" "$EWA_CORE" || { echo "FATAL: BOOST token mismatch"; exit 1; }
sleep 5


# ===== EVA_CongestionExit =====
echo "=== EVA_CongestionExit ==="
CONGEXIT_
CONGEXIT_ARGS=$(cast abi-encode "constructor(address,uint256,uint256,uint256,uint64,uint64,uint64)" $EWA_CORE 200 4000000000000000000 2500 604800 2592000 31536000)
CONGEXIT_ARGS=${CONGEXIT_ARGS#0x}
CONGEXIT=$(cast send --rpc-url $RPC --private-key $PK --create ${CONGEXIT_BC}${CONGEXIT_ARGS} | grep -i contractAddress | awk '{print $2}')
if [ -z "${CONGEXIT:-}" ]; then echo "FATAL: EVA_CongestionExit deploy failed"; exit 1; fi
echo "EVA_CongestionExit = $CONGEXIT"
save_addr CONGEXIT $CONGEXIT
sleep 5
eq_addr "$(cast call $CONGEXIT "EVA()(address)" --rpc-url $RPC)" "$EWA_CORE" || { echo "FATAL: CONGEXIT token mismatch"; exit 1; }
sleep 5


# ===== EVA_LoyaltyBadge =====
echo "=== EVA_LoyaltyBadge ==="
BADGE_
BADGE_ARGS=$(cast abi-encode "constructor(address,address,string,uint256[4])" $EWA_CORE $FOUNDER "" "[1000000000000000000000,10000000000000000000000,100000000000000000000000,1000000000000000000000000]")
BADGE_ARGS=${BADGE_ARGS#0x}
BADGE=$(cast send --rpc-url $RPC --private-key $PK --create ${BADGE_BC}${BADGE_ARGS} | grep -i contractAddress | awk '{print $2}')
if [ -z "${BADGE:-}" ]; then echo "FATAL: EVA_LoyaltyBadge deploy failed"; exit 1; fi
echo "EVA_LoyaltyBadge = $BADGE"
save_addr BADGE $BADGE
sleep 5
eq_addr "$(cast call $BADGE "TOKEN()(address)" --rpc-url $RPC)" "$EWA_CORE" || { echo "FATAL: BADGE token mismatch"; exit 1; }
sleep 5


# ===== EVA_Splitter =====
echo "=== EVA_Splitter ==="
SPLITTER_
SPLITTER_ARGS=$(cast abi-encode "constructor(address[],uint256[])" "[$FOUNDER]" "[10000]")
SPLITTER_ARGS=${SPLITTER_ARGS#0x}
SPLITTER=$(cast send --rpc-url $RPC --private-key $PK --create ${SPLITTER_BC}${SPLITTER_ARGS} | grep -i contractAddress | awk '{print $2}')
if [ -z "${SPLITTER:-}" ]; then echo "FATAL: EVA_Splitter deploy failed"; exit 1; fi
echo "EVA_Splitter = $SPLITTER"
save_addr SPLITTER $SPLITTER
sleep 5
[ "$(cast call $SPLITTER "totalShares()(uint256)" --rpc-url $RPC)" = "10000" ] || { echo "FATAL: SPLITTER shares mismatch"; exit 1; }
sleep 5


# ===== EVAFounderVesting =====
echo "=== EVAFounderVesting ==="
FVEST_
FVEST_ARGS=$(cast abi-encode "constructor(address,address,uint256,uint64,uint64,uint256,uint64)" $EWA_CORE $FOUNDER 2000000000000000000000000 31536000 94608000 500000000000000000000000 31536000)
FVEST_ARGS=${FVEST_ARGS#0x}
FVEST=$(cast send --rpc-url $RPC --private-key $PK --create ${FVEST_BC}${FVEST_ARGS} | grep -i contractAddress | awk '{print $2}')
if [ -z "${FVEST:-}" ]; then echo "FATAL: EVAFounderVesting deploy failed"; exit 1; fi
echo "EVAFounderVesting = $FVEST"
save_addr FVEST $FVEST
sleep 5
[ "$(cast call $FVEST "TOTAL()(uint256)" --rpc-url $RPC)" = "2500000000000000000000000" ] || { echo "FATAL: FVEST total mismatch"; exit 1; }
sleep 5

echo "  BOOST=${BOOST:-MISSING}"
echo "  CONGEXIT=${CONGEXIT:-MISSING}"
echo "  BADGE=${BADGE:-MISSING}"
echo "  SPLITTER=${SPLITTER:-MISSING}"
echo "  FVEST=${FVEST:-MISSING}"
echo "Full record: $ADDR_FILE"
echo "=================================================================="
